require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/Connectors.php';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);header('Allow: POST');exit('Metode tidak diizinkan.');}verify_csrf();$workspace=require_permission('connect');$sourceId=filter_var($_POST['source_id']??null,FILTER_VALIDATE_INT);try{$datasetId=DatanixConnectors::sync((int)$sourceId,(int)$workspace['id'],(int)current_user()['id']);flash('success','Sumber tersinkron. Snapshot dataset diperbarui pada '.$datasetId.'.');}catch(Throwable $e){error_log('Datanix source sync failed: '.substr($e->getMessage(),0,350));flash('error','Sync belum berhasil: '.$e->getMessage());}$GLOBALS['pdo']->prepare('UPDATE data_sources SET status=?,error_message=? WHERE id=? AND workspace_id=?')->execute([isset($e)?'error':'connected',isset($e)?mb_substr($e->getMessage(),0,500,'UTF-8'):null,$sourceId,$workspace['id']]);redirect('datasets/sources.php');
